window.kbPageData["views/entry/k-8895db69aedcad85"] = {"key":"entry/k-8895db69aedcad85","state":{"route":"entry/k-8895db69aedcad85"},"node":{"id":"k-8895db69aedcad85","mode":"k","title":"新型基础设施","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["industry"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["非时政"]},"directorySummary":"3.新型基础设施\n新型基础设施是指提供数字转型、智能升级、融合创新等服务的基础设施体系，主要包\n括信息基础设施、融合基础设施和创新基础设施。信息基础设施是指基于新一代信息技术演\n化生成的基础设施，如第五代移动通信技术、物联网、数据中心、人工智能、卫星通信、区\n块链基础设施等。融合基础设施是指传统基础…","sources":[{"id":"0a7fde78b5c0c464","label":"新型基础设施","topic":"产业、科技与对外开放","category":"非时政","text":"3.新型基础设施\n新型基础设施是指提供数字转型、智能升级、融合创新等服务的基础设施体系，主要包\n括信息基础设施、融合基础设施和创新基础设施。信息基础设施是指基于新一代信息技术演\n化生成的基础设施，如第五代移动通信技术、物联网、数据中心、人工智能、卫星通信、区\n块链基础设施等。融合基础设施是指传统基础设施应用新一代信息技术进行智能化改造后所\n形成的基础设施形态，包括以工业互联网、智慧交通物流设施、智慧能源系统为代表的新型\n生产性设施，和以智慧民生基础设施、智慧环境资源设施、智慧城市基础设施等为代表的新\n型社会性设施。创新基础设施是指支撑科学研究、技术开发、新产品和新服务研制的具有公\n益属性的基础设施，包括重大科技基础设施、科教基础设施、产业技术基础设施等。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":21,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-8895db69aedcad85":[]}};
